"""
Adapter module: defines interfaces and minimal concrete implementations to
reduce coupling between core WebSocket server components and tests.

This module enables dependency injection and test isolation while preserving
the public API of the parent package.
"""

import threading
from abc import ABC, abstractmethod

from .thread import WebsocketServerThread


class MessageHandler(ABC):
    """Interface for handling protocol-level messages."""

    @abstractmethod
    def on_text_message(self, handler, message_str: str):
        pass

    @abstractmethod
    def on_ping(self, handler, payload: bytes):
        pass

    @abstractmethod
    def on_pong(self, handler, payload: bytes):
        pass


class ClientManager(ABC):
    """Interface for managing connected clients."""

    @abstractmethod
    def register(self, handler, client_address) -> dict:
        """Register a new client, returns the client dict."""
        pass

    @abstractmethod
    def unregister(self, handler):
        """Unregister a client by handler."""
        pass

    @abstractmethod
    def get_client_for_handler(self, handler) -> dict:
        """Lookup client dict by handler."""
        pass

    @abstractmethod
    def broadcast(self, msg: str):
        """Send message to all connected clients."""
        pass


class HandshakeValidator(ABC):
    """Interface for WebSocket handshake validation."""

    @abstractmethod
    def validate(self, headers: dict) -> bool:
        pass

    @abstractmethod
    def build_response(self, key: str) -> str:
        pass


class ThreadingRunner(ABC):
    """Interface for server lifecycle and threading."""

    @abstractmethod
    def run_forever(self, threaded: bool = False):
        pass

    @abstractmethod
    def shutdown_gracefully(self):
        pass

    @abstractmethod
    def shutdown_abruptly(self):
        pass

    @abstractmethod
    def server_close(self):
        pass


class WebSocketMessageHandler(MessageHandler):
    """
    Concrete handler that delegates protocol events to a server instance.
    Decouples frame decoding from application callbacks.
    """

    def __init__(self, server):
        self.server = server

    def on_text_message(self, handler, message_str: str):
        self.server._message_received_(handler, message_str)

    def on_ping(self, handler, payload: bytes):
        self.server._ping_received_(handler, payload)

    def on_pong(self, handler, payload: bytes):
        self.server._pong_received_(handler, payload)


class WebSocketClientManager(ClientManager):
    """
    Concrete client registry that coordinates with a server instance.
    Encapsulates client list and ID generation to reduce coupling.
    """

    def __init__(self, server):
        self.server = server
        self.clients = []
        self.id_counter = 0
        self._lock = threading.Lock()

    def register(self, handler, client_address):
        with self._lock:
            self.id_counter += 1
            client = {
                'id': self.id_counter,
                'handler': handler,
                'address': client_address,
            }
            self.clients.append(client)
            return client

    def unregister(self, handler):
        with self._lock:
            for idx, client in enumerate(self.clients):
                if client['handler'] == handler:
                    self.clients.pop(idx)
                    break

    def get_client_for_handler(self, handler) -> dict:
        with self._lock:
            for client in self.clients:
                if client['handler'] == handler:
                    return client
        return None

    def broadcast(self, msg: str):
        with self._lock:
            for client in list(self.clients):
                try:
                    client['handler'].send_message(msg)
                except Exception:
                    pass


class WebSocketHandshakeValidator(HandshakeValidator):
    """
    Minimal concrete implementation of handshake validation.
    Keeps logic for key derivation and handshake response generation
    isolated from core handler logic.
    """

    @staticmethod
    def calculate_response_key(key: str) -> str:
        from base64 import b64encode
        from hashlib import sha1
        mask = b'258EAFA5-E914-47DA-95CA-C5AB0DC85B11'
        return b64encode(sha1(key.encode() + mask).digest()).decode()

    def validate(self, headers: dict) -> bool:
        return (
            headers.get('upgrade', '').lower() == 'websocket' and
            'sec-websocket-key' in headers
        )

    def build_response(self, key: str) -> str:
        response_key = self.calculate_response_key(key)
        return (
            'HTTP/1.1 101 Switching Protocols\r\n'
            'Upgrade: websocket\r\n'
            'Connection: Upgrade\r\n'
            f'Sec-WebSocket-Accept: {response_key}\r\n'
            '\r\n'
        )


class ThreadingRunnerImpl(ThreadingRunner):
    """
    Concrete runner that wraps threading behavior, allowing tests to
    substitute server execution without affecting core protocol logic.
    """

    def __init__(self, server):
        self.server = server
        self._thread = None
        self._logger = server._logger

    def run_forever(self, threaded: bool = False):
        try:
            self._logger.info("Listening on port %d for clients.." % self.server.port)
            if threaded:
                self._thread = WebsocketServerThread(
                    target=self.server._base_serve_forever,
                    daemon=True,
                    logger=self._logger
                )
                self._thread.start()
            else:
                self._thread = None
                self.server._base_serve_forever()
        except KeyboardInterrupt:
            self.server.server_close()
            self._logger.info("Server terminated.")
        except Exception as e:
            self._logger.error(str(e), exc_info=True)
            import sys
            sys.exit(1)

    def shutdown_gracefully(self):
        self.server._shutdown_gracefully()

    def shutdown_abruptly(self):
        self.server._shutdown_abruptly()

    def server_close(self):
        self.server._base_server_close()
